private static void SiftDown(int[] nums, int start, int end)
{
    int root = start;

    while (2 * root + 1 <= end)
    {
        int child = 2 * root + 1;

        // Pick the larger of the two children
        if (child + 1 <= end && nums[child] < nums[child + 1])
        {
            child++;
        }

        if (nums[root] < nums[child])
        {
            (nums[root], nums[child]) = (nums[child], nums[root]);
            root = child;
        }
        else
        {
            return; // heap property restored
        }
    }
}

public void HeapSort(int[] nums)
{
    int n = nums.Length;

    // Phase 1: build a max-heap bottom-up (O(n))
    for (int start = n / 2 - 1; start >= 0; start--)
    {
        SiftDown(nums, start, n - 1);
    }

    // Phase 2: repeatedly move the max to the end
    for (int end = n - 1; end > 0; end--)
    {
        (nums[0], nums[end]) = (nums[end], nums[0]); // max goes to the sorted suffix
        SiftDown(nums, 0, end - 1);                    // restore the heap
    }
}

public void HeapSort(int[] nums)
{
    int n = nums.Length;

    for (int start = n / 2 - 1; start >= 0; start--)
        SiftDown(nums, start, n - 1);

    for (int end = n - 1; end > 0; end--)
    {
        (nums[0], nums[end]) = (nums[end], nums[0]);
        SiftDown(nums, 0, end - 1);
    }
}

private static void SiftDown(int[] nums, int start, int end)
{
    int root = start;

    while (2 * root + 1 <= end)
    {
        int child = 2 * root + 1;
        if (child + 1 <= end && nums[child] < nums[child + 1]) child++;

        if (nums[root] < nums[child])
        {
            (nums[root], nums[child]) = (nums[child], nums[root]);
            root = child;
        }
        else return;
    }
}
